285	// Deliver the converge as one commit on the per-cycle maintenance branch, native
286	// git. Reuses the family's open PR (by prefix) or mints a dated branch + PR;
287	// arms auto-merge when the member asked for it. Force-push is the regenerate-not-
288	// reconcile stance for this bot-owned branch.
289	async function deliver(root, repo, base, token, delivery, seed) {
290	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
291	  let pr = openMaintenancePull(Array.isArray(pulls) ? pulls : []);
292	  const reuse = Boolean(pr);
293	  let branch = reuse ? pr.head.ref : maintenanceBranchName(new Date().toISOString().slice(0, 10), seed);
294	
295	  git(['-C', root, 'checkout', '-B', branch]);
296	  git(['-C', root, 'add', '-A']);
297	  git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
298	    'commit', '-m', 'Claudinite maintenance: converge vendored mount, wiring, and migration notes']);
299	  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
300	  git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
301	
302	  if (!reuse) {
303	    const body = delivery === 'auto-merge'
304	      ? 'Automated Claudinite maintenance (deterministic converge + any migration notes). Regenerated each cycle; auto-merges once this repo\'s checks pass.'
305	      : 'Automated Claudinite maintenance (deterministic converge + any migration notes). Regenerated each cycle; left for your review.';
306	    const created = await gh(token, `/repos/${repo}/pulls`, {
307	      method: 'POST', body: { head: branch, base, title: 'Claudinite maintenance', body },
308	    });
309	    const failure = pullCreateError(created.status, created.json);
310	    if (failure) throw new Error(`could not open the maintenance PR for ${branch}: ${failure}`);
311	    pr = created.json;
312	  }
