314	  // ARM GitHub's native auto-merge (not an immediate merge): the PR lands
315	  // automatically once this repo's required checks pass, and the run never blocks
316	  // on CI. Auto-merge is a GraphQL-only mutation.
317	  //
318	  // RE-ASSERTED EVERY CYCLE, reuse or not. The arm is best-effort, and there are
319	  // three ordinary ways for it to be absent from an open maintenance PR: the
320	  // mutation failed when the PR was opened; the repo had not enabled auto-merge
321	  // yet (a settings change nothing here can see); or the member flipped
322	  // `maintenance.delivery` from `review` to `auto-merge` while this PR was
323	  // already open. Arming only on the opening cycle left all three unrecoverable —
324	  // every later run reuses the branch and never retried, so the PR sat open
325	  // forever. The stable-PR form this superseded re-asserted the arm on every run;
326	  // this restores that. Idempotent: arming an already-armed PR is a no-op.
327	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open above emitted no
328	  // pull_request event, so without this the PR has no runs (#565, the
329	  // ciDispatchPlan block). AFTER the push, so the dispatched runs execute the
330	  // branch's own head; every delivering cycle, since a force-push emits no
331	  // synchronize event either and each new head needs its own runs. Best-effort:
332	  // a dispatch failure must not fail the converge that was already pushed.
333	  //
334	  // It runs BEFORE the delivery decision because it is what establishes whether
335	  // this repo has any PR CI at all — the fact deliveryAction turns on.
336	  const ci = await dispatchCiRuns(token, repo, branch)
337	    .catch((e) => { console.log(`baselining: CI dispatch on ${branch} failed: ${e.message}`); return null; });
338	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
339	
340	  if (pr?.number) {
341	    const action = deliveryAction({ delivery, hasPrCi });
342	    if (action === 'merge') {
343	      const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
344	        method: 'PUT', body: { merge_method: 'squash' },
345	      });
346	      if (res.status === 200) console.log(`baselining: merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`);
