348	    } else if (action === 'arm' && pr.node_id) {
349	      // Surfaced, not swallowed: a failed arm is why a maintenance PR sits open
350	      // forever, and the two usual causes are both fixable repo settings.
351	      await enableAutoMerge(token, pr.node_id)
352	        .catch((e) => console.log(`baselining: could not arm auto-merge on PR #${pr.number}: ${e.message}`
353	          + ' — check Settings → General → "Allow auto-merge"'));
354	    }
355	  }
356	  return branch;
